  'tour.action.accessibility': 'Einstellungen → Barrierefreiheit öffnen',
  'tour.step.welcome.title': 'Willkommen bei Foreman',
  'tour.step.welcome.body': 'Lass Coding-Agenten parallel arbeiten, jeden auf seinem eigenen Branch in seiner eigenen Kopie deines Repositorys. Alles bleibt auf diesem Computer. Hier siehst du, wo was ist.',
  'tour.step.addRepo.title': 'Repository hinzufügen',
  'tour.step.addRepo.body': 'Öffne einen Ordner, der bereits ein Git-Repository ist, klone eines von GitHub oder lege mit Schnellstart ein neues an. Mit einem Rechtsklick auf ein Repository öffnest du seine Einstellungen: Setup-Skript, Run-Skript und Prüfungen.',
  'tour.step.addRepo.where': 'die +-Schaltfläche in der Leiste der Repository-Symbole',
  'tour.step.newWorkspace.title': 'Arbeitsbereich starten',
  'tour.step.newWorkspace.body': 'Jeder Arbeitsbereich ist ein neuer Branch in einem eigenen Worktree, mit eigenen Ports und eigenem Terminal, sodass sich Agenten nie in die Quere kommen. Drück {key} und beschreib die Aufgabe; Bilder gehen auch.',
  'tour.step.newWorkspace.where': 'die Schaltfläche „Neuer Arbeitsbereich“ oben',
  'tour.step.needsYou.title': 'Braucht dich',
  'tour.step.needsYou.body': 'Wenn mehrere Agenten laufen, schaust du ihnen nicht mehr zu. Alles, was auf dich wartet (eine Freigabe, eine Frage, ein Plan, ein fehlgeschlagener Durchlauf), wird hier und auf der Startseite gesammelt, mit Zähler, Benachrichtigung und Badge in Tray oder Menüleiste. {next} springt zum nächsten Arbeitsbereich, der dich braucht; {jump} zu dem, was im aktuellen Chat auf dich wartet.',
  'tour.step.needsYou.where': 'die Filter Alle, Braucht dich, Läuft und Angeheftet',
  'tour.step.layout.title': 'Zwei Arten, deine Arbeit zu sehen',
  'tour.step.layout.body': 'Drei Bereiche zeigt einen Arbeitsbereich mit seinen Änderungen und dem Terminal daneben; das hast du jetzt. Kacheln zeigt die Chats mehrerer Arbeitsbereiche nebeneinander. Wechsle jederzeit mit {palette} („Zu Kacheln wechseln“) oder unter Einstellungen → Darstellung → Fensterlayout.',
  'tour.step.automations.title': 'Vorlagen und Automationen',
  'tour.step.automations.body': 'Vorlagen sind Prompts mit Lücken für die Details; behalte eigene oder die des Repositorys. Automationen führen eine Vorlage nach Zeitplan aus (täglich, wöchentlich usw.), solange Foreman geöffnet ist, mit einem Kalender dessen, was lief und was als Nächstes kommt.',
  'tour.step.automations.where': 'Automationen oben in der Seitenleiste',
  'tour.step.assistant.title': 'Den Assistenten fragen',
  'tour.step.assistant.body': 'Du weißt nicht, wo etwas ist? Frag hier ({key}). Er zeigt dir die genaue Einstellung und ändert nie etwas. Er läuft mit Claude, melde dich also zuerst bei Claude an.',
  'tour.step.assistant.where': 'Assistent unter Automationen',
  'tour.step.settings.title': 'Einstellungen',
  'tour.step.settings.body': 'Barrierefreiheit: Textgröße, Zoom, Farbmodi und Ansagen für Screenreader. Agenten: anmelden und Standard wählen. MCP: Repository-Server werden im Git-Panel eines Arbeitsbereichs freigegeben, und Agenten erhalten Foremans eigene Werkzeuge. Remote-Arbeitsbereiche (experimentell, standardmäßig aus) führen einen Arbeitsbereich in einer Cloud-Sandbox aus.',
  'tour.step.settings.where': 'das Zahnrad in der Leiste der Repository-Symbole',
  'tour.step.help.title': 'Hierher zurückfinden',
  'tour.step.help.body': 'Starte diese Tour hier erneut. Alles andere findest du per Suche: {palette} öffnet die Befehlspalette, {shortcuts} zeigt alle Tastenkürzel.',
  'tour.step.help.where': 'das ? in der Leiste der Repository-Symbole',

